import React from 'react';

function Navbar({ currentPage, setCurrentPage, cartCount, onLogout }) {
  return (
    <nav className="navbar">
      <div className="nav-content">
        <div className="nav-left">
          <button 
            className={`nav-link ${currentPage === 'landing' ? 'active' : ''}`} 
            onClick={() => setCurrentPage('landing')}
            type="button"
            aria-label="Go to Home page"
          >
            Home
          </button>
          <button 
            className={`nav-link ${currentPage === 'menu' ? 'active' : ''}`} 
            onClick={() => setCurrentPage('menu')}
            type="button"
            aria-label="Go to Menu page"
          >
            Menu
          </button>
          <button 
            className={`nav-link ${currentPage === 'profile' ? 'active' : ''}`} 
            onClick={() => setCurrentPage('profile')}
            type="button"
            aria-label="Go to Profile page"
          >
            Profile
          </button>
        </div>
        <div className="logo">🍽️ Apsit Canteen</div>
        <div className="nav-right">
          <button 
            className={`nav-link ${currentPage === 'cart' ? 'active' : ''}`} 
            onClick={() => setCurrentPage('cart')}
            type="button"
            aria-label={`Go to Cart page, ${cartCount} items in cart`}
          >
            Cart <span className="cart-badge">{cartCount}</span>
          </button>
          <button 
            className="nav-link" 
            onClick={onLogout}
            type="button"
            aria-label="Logout from account"
          >
            Logout
          </button>
        </div>
      </div>
    </nav>
  );
}

export default Navbar;
